/// `page` with the knobs beside it: put it where the page would go, filling the window. Read
/// [`Knobs::side_room`] for the width the page loses while it's open.
#[napi(js_name = "knobs_side", skip_typescript)]
pub fn f_knobs_side(a_page: Raw, a_k: Raw, a_groups: Raw, a_st: Raw, a_lens: Raw) -> napi::Result<Raw> {
    conv::guard(|| {
        let a_page: rune::El = conv::arg(a_page.0, "page")?;
        let mut a_k_i = conv::instance::<crate::gen::knobs::W_knobs_Knobs>(a_k.0).map_err(|e| conv::err(format!("{}: {}", "k", e.reason)))?;
        let a_k = a_k_i.slot().get("Knobs")?;
        let a_groups: Vec<rune_knobs::Group> = conv::arg(a_groups.0, "groups")?;
        let a_groups: &'static [rune_knobs::Group] = Box::leak(a_groups.into_boxed_slice());
        let a_st: rune_knobs::Style = conv::arg(a_st.0, "st")?;
        let a_lens = crate::gen::tramp::t10_register(a_lens.0).map_err(|e| conv::err(format!("{}: {}", "lens", e.reason)))?;
        let out = conv::ToJs::to_js(rune_knobs::side(a_page, a_k, a_groups, a_st, a_lens))?;
        Ok(Raw(out))
    })
}

